"use client";

import "./toggle.css";
import { Toggle as BaseToggle } from "@base-ui/react/toggle";
import type React from "react";
import { cn } from "tailwind-variants";

import { ToggleContext } from "./toggle.context";
import { toggleVariants, type ToggleVariants } from "./toggle.variants";

export type ToggleProps = ToggleVariants & React.ComponentProps<typeof BaseToggle>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/toggle/content.md
 */
export const ToggleRoot = ({ children, className, variant, size, ...props }: ToggleProps) => {
  const slots = toggleVariants({ variant, size });

  return (
    <ToggleContext.Provider value={{ slots }}>
      <BaseToggle className={cn(slots.root(), className)} {...props}>
        {children}
      </BaseToggle>
    </ToggleContext.Provider>
  );
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const toggleVariants = tv({
  slots: {
    root: "toggle",
  },
  variants: {
    variant: {
      default: {
        root: "bg-transparent hover:bg-muted hover:text-muted-foreground data-pressed:bg-accent data-pressed:text-accent-foreground",
      },
      outline: {
        root: "border border-input bg-transparent hover:bg-accent hover:text-accent-foreground data-pressed:bg-accent data-pressed:text-accent-foreground",
      },
    },
    size: {
      sm: {
        root: "h-8 px-2 min-w-8 text-xs gap-1.5",
      },
      md: {
        root: "h-9 px-2.5 min-w-9 text-sm gap-2",
      },
      lg: {
        root: "h-10 px-3 min-w-10 text-base gap-2.5",
      },
    },
  },
  defaultVariants: {
    variant: "default",
    size: "md",
  },
});

export type ToggleVariants = VariantProps<typeof toggleVariants>;

"use client";

import { createContext, useContext } from "react";

import { toggleVariants } from "./toggle.variants";

export type ToggleContext = {
  slots: ReturnType<typeof toggleVariants>;
};

export const ToggleContext = createContext<ToggleContext | null>(null);

export const useToggleContext = () => {
  const context = useContext(ToggleContext);
  return context ?? { slots: toggleVariants() };
};

.toggle {
  @apply text-foreground focus-visible:outline-ring inline-flex cursor-pointer items-center justify-center rounded-md text-sm font-medium transition-colors outline-none select-none focus-visible:outline-2 disabled:pointer-events-none disabled:opacity-50;
}

import { ToggleRoot } from "./toggle";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/toggle/content.md
 */
export const Toggle = {
  Root: ToggleRoot,
};

export { ToggleRoot };

export type { ToggleProps } from "./toggle";
export { ToggleContext, useToggleContext } from "./toggle.context";
export { type ToggleVariants, toggleVariants } from "./toggle.variants";
